const STAGES = ['待投递', '已投递', '面试中', '已结束'];
const STORE_KEY = 'jobApplicationBoard';

const state = {
  records: [],
  filter: '全部',
  editingId: null,
  pendingDeleteId: null,
};

const el = {};

function cacheEls() {
  el.totalCount = document.querySelector('[data-role="total-count"]');
  el.statsGrid = document.querySelector('[data-role="stats-grid"]');
  el.formTitle = document.querySelector('[data-role="form-title"]');
  el.cancelEdit = document.querySelector('[data-role="cancel-edit"]');
  el.form = document.querySelector('[data-role="record-form"]');
  el.company = document.querySelector('[data-role="input-company"]');
  el.position = document.querySelector('[data-role="input-position"]');
  el.date = document.querySelector('[data-role="input-date"]');
  el.stage = document.querySelector('[data-role="input-stage"]');
  el.note = document.querySelector('[data-role="input-note"]');
  el.formError = document.querySelector('[data-role="form-error"]');
  el.submitBtn = document.querySelector('[data-role="submit-btn"]');
  el.resetBtn = document.querySelector('[data-role="reset-btn"]');
  el.filterBar = document.querySelector('[data-role="filter-bar"]');
  el.recordList = document.querySelector('[data-role="record-list"]');
  el.visibleCount = document.querySelector('[data-role="visible-count"]');
  el.emptyHint = document.querySelector('[data-role="empty-hint"]');
  el.dialogBackdrop = document.querySelector('[data-role="dialog-backdrop"]');
  el.dialogTitle = document.querySelector('[data-role="dialog-title"]');
  el.dialogDesc = document.querySelector('[data-role="dialog-desc"]');
  el.dialogCancel = document.querySelector('[data-role="dialog-cancel"]');
  el.dialogConfirm = document.querySelector('[data-role="dialog-confirm"]');
}

function todayISO() {
  const d = new Date();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return d.getFullYear() + '-' + m + '-' + day;
}

function normalizeStage(value) {
  return STAGES.indexOf(value) >= 0 ? value : STAGES[0];
}

function normalizeRecord(raw) {
  const source = raw && typeof raw === 'object' ? raw : {};
  const record = Object.assign({}, source);
  record.id = typeof source.id === 'string' && source.id ? source.id : 'rec-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 8);
  record.company = typeof source.company === 'string' ? source.company : '';
  record.position = typeof source.position === 'string' ? source.position : '';
  record.applyDate = typeof source.applyDate === 'string' ? source.applyDate : '';
  record.stage = normalizeStage(source.stage);
  record.note = typeof source.note === 'string' ? source.note : '';
  return record;
}

function normalizeState(raw) {
  const source = raw && typeof raw === 'object' ? raw : {};
  const next = Object.assign({}, source);
  next.records = Array.isArray(source.records) ? source.records.map(normalizeRecord) : [];
  return next;
}

function buildStageOptions() {
  el.stage.textContent = '';
  STAGES.forEach(function (stage) {
    const option = document.createElement('option');
    option.value = stage;
    option.textContent = stage;
    el.stage.appendChild(option);
  });
}

function buildFilterChips() {
  el.filterBar.textContent = '';
  const options = ['全部'].concat(STAGES);
  options.forEach(function (name) {
    const chip = document.createElement('button');
    chip.type = 'button';
    chip.className = 'filter-chip';
    chip.dataset.filter = name;
    chip.textContent = name;
    if (state.filter === name) {
      chip.classList.add('is-active');
    }
    chip.addEventListener('click', function () {
      state.filter = name;
      render();
    });
    el.filterBar.appendChild(chip);
  });
}

function computeStats() {
  const counts = {};
  STAGES.forEach(function (stage) {
    counts[stage] = 0;
  });
  state.records.forEach(function (record) {
    const stage = normalizeStage(record.stage);
    counts[stage] += 1;
  });
  return counts;
}

function renderStats() {
  const counts = computeStats();
  const total = state.records.length;
  el.totalCount.textContent = String(total);
  el.statsGrid.textContent = '';
  STAGES.forEach(function (stage) {
    const item = document.createElement('li');
    item.className = 'stat-item';

    const name = document.createElement('span');
    name.className = 'stat-name';
    name.textContent = stage;

    const value = document.createElement('span');
    value.className = 'stat-value';
    value.dataset.stage = stage;
    value.textContent = String(counts[stage]);

    item.appendChild(name);
    item.appendChild(value);
    el.statsGrid.appendChild(item);
  });
}

function getVisibleRecords() {
  if (state.filter === '全部') {
    return state.records.slice();
  }
  return state.records.filter(function (record) {
    return normalizeStage(record.stage) === state.filter;
  });
}

function renderList() {
  const visible = getVisibleRecords();
  el.visibleCount.textContent = String(visible.length);
  el.recordList.textContent = '';

  visible.forEach(function (record) {
    const card = document.createElement('li');
    card.className = 'record-card';
    card.dataset.recordId = record.id;

    const top = document.createElement('div');
    top.className = 'record-top';

    const titleWrap = document.createElement('div');
    const company = document.createElement('h3');
    company.className = 'record-company';
    company.textContent = record.company || '（未填写公司）';
    const position = document.createElement('p');
    position.className = 'record-position';
    position.textContent = record.position || '（未填写岗位）';
    titleWrap.appendChild(company);
    titleWrap.appendChild(position);

    const badge = document.createElement('span');
    badge.className = 'stage-badge';
    badge.dataset.stage = normalizeStage(record.stage);
    badge.textContent = normalizeStage(record.stage);

    top.appendChild(titleWrap);
    top.appendChild(badge);
    card.appendChild(top);

    const meta = document.createElement('div');
    meta.className = 'record-meta';
    const dateSpan = document.createElement('span');
    dateSpan.textContent = '投递日期：' + (record.applyDate || '未填写');
    meta.appendChild(dateSpan);
    card.appendChild(meta);

    if (record.note) {
      const note = document.createElement('p');
      note.className = 'record-note';
      note.textContent = record.note;
      card.appendChild(note);
    }

    const actions = document.createElement('div');
    actions.className = 'record-actions';

    const editBtn = document.createElement('button');
    editBtn.type = 'button';
    editBtn.className = 'btn btn-ghost btn-small';
    editBtn.dataset.action = 'edit';
    editBtn.dataset.recordId = record.id;
    editBtn.textContent = '编辑';

    const deleteBtn = document.createElement('button');
    deleteBtn.type = 'button';
    deleteBtn.className = 'btn btn-danger btn-small';
    deleteBtn.dataset.action = 'delete';
    deleteBtn.dataset.recordId = record.id;
    deleteBtn.textContent = '删除';

    actions.appendChild(editBtn);
    actions.appendChild(deleteBtn);
    card.appendChild(actions);

    el.recordList.appendChild(card);
  });

  if (visible.length === 0) {
    el.emptyHint.hidden = false;
    if (state.records.length === 0) {
      el.emptyHint.textContent = '还没有投递记录，先在上方添加第一条吧。';
    } else {
      el.emptyHint.textContent = '当前筛选「' + state.filter + '」下暂无记录。';
    }
  } else {
    el.emptyHint.hidden = true;
    el.emptyHint.textContent = '';
  }
}

function render() {
  renderStats();
  buildFilterChips();
  renderList();
}

function showFormError(message) {
  if (message) {
    el.formError.textContent = message;
    el.formError.hidden = false;
  } else {
    el.formError.textContent = '';
    el.formError.hidden = true;
  }
}

function clearForm() {
  el.company.value = '';
  el.position.value = '';
  el.date.value = todayISO();
  el.stage.value = STAGES[0];
  el.note.value = '';
  showFormError('');
}

function setEditingMode(record) {
  state.editingId = record ? record.id : null;
  if (record) {
    el.formTitle.textContent = '编辑投递记录';
    el.submitBtn.textContent = '保存修改';
    el.cancelEdit.hidden = false;
    el.company.value = record.company;
    el.position.value = record.position;
    el.date.value = record.applyDate;
    el.stage.value = normalizeStage(record.stage);
    el.note.value = record.note;
    showFormError('');
  } else {
    el.formTitle.textContent = '新增投递记录';
    el.submitBtn.textContent = '添加记录';
    el.cancelEdit.hidden = true;
    clearForm();
  }
}

async function persist(nextRecords) {
  const current = await appStore.getState();
  const base = current && typeof current === 'object' ? current : {};
  const next = Object.assign({}, base);
  next.records = nextRecords;
  await appStore.setState(next);
}

async function handleSubmit(event) {
  event.preventDefault();
  const company = el.company.value.trim();
  const position = el.position.value.trim();
  const applyDate = el.date.value;
  const stage = normalizeStage(el.stage.value);
  const note = el.note.value.trim();

  if (!company) {
    showFormError('请填写公司名称。');
    el.company.focus();
    return;
  }
  if (!position) {
    showFormError('请填写岗位名称。');
    el.position.focus();
    return;
  }
  if (!applyDate) {
    showFormError('请选择投递日期。');
    el.date.focus();
    return;
  }

  showFormError('');

  if (state.editingId) {
    const nextRecords = state.records.map(function (record) {
      if (record.id !== state.editingId) {
        return record;
      }
      return Object.assign({}, record, {
        company: company,
        position: position,
        applyDate: applyDate,
        stage: stage,
        note: note,
      });
    });
    try {
      await persist(nextRecords);
    } catch (error) {
      showFormError('保存失败，请重试。你的输入已保留。');
      return;
    }
    state.records = nextRecords;
    setEditingMode(null);
    render();
    return;
  }

  const newRecord = normalizeRecord({
    id: 'rec-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 8),
    company: company,
    position: position,
    applyDate: applyDate,
    stage: stage,
    note: note,
  });
  const nextRecords = state.records.concat([newRecord]);
  try {
    await persist(nextRecords);
  } catch (error) {
    showFormError('保存失败，请重试。你的输入已保留。');
    return;
  }
  state.records = nextRecords;
  clearForm();
  render();
}

function openDeleteDialog(record) {
  state.pendingDeleteId = record.id;
  el.dialogTitle.textContent = '确认删除';
  el.dialogDesc.textContent = '确定要删除「' + (record.company || '未填写公司') + ' · ' + (record.position || '未填写岗位') + '」这条投递记录吗？删除后无法恢复。';
  el.dialogBackdrop.hidden = false;
  el.dialogConfirm.focus();
}

function closeDeleteDialog() {
  state.pendingDeleteId = null;
  el.dialogBackdrop.hidden = true;
}

async function confirmDelete() {
  const id = state.pendingDeleteId;
  if (!id) {
    closeDeleteDialog();
    return;
  }
  const nextRecords = state.records.filter(function (record) {
    return record.id !== id;
  });
  try {
    await persist(nextRecords);
  } catch (error) {
    closeDeleteDialog();
    showFormError('删除失败，请重试。');
    return;
  }
  state.records = nextRecords;
  if (state.editingId === id) {
    setEditingMode(null);
  }
  closeDeleteDialog();
  render();
}

function handleListClick(event) {
  const target = event.target;
  if (!target || typeof target.closest !== 'function') {
    return;
  }
  const button = target.closest('button[data-action]');
  if (!button) {
    return;
  }
  const id = button.dataset.recordId;
  const record = state.records.filter(function (item) {
    return item.id === id;
  })[0];
  if (!record) {
    return;
  }
  if (button.dataset.action === 'edit') {
    setEditingMode(record);
    el.company.focus();
  } else if (button.dataset.action === 'delete') {
    openDeleteDialog(record);
  }
}

async function init() {
  cacheEls();
  buildStageOptions();

  const raw = await appStore.getState();
  const normalized = normalizeState(raw);
  state.records = normalized.records;

  if (!raw || !Array.isArray(raw.records)) {
    try {
      await persist(state.records);
    } catch (error) {
      /* 初始化写入失败时保持内存状态可用 */
    }
  }

  el.form.addEventListener('submit', handleSubmit);
  el.resetBtn.addEventListener('click', function () {
    if (state.editingId) {
      setEditingMode(null);
    } else {
      clearForm();
    }
  });
  el.cancelEdit.addEventListener('click', function () {
    setEditingMode(null);
  });
  el.recordList.addEventListener('click', handleListClick);
  el.dialogCancel.addEventListener('click', closeDeleteDialog);
  el.dialogConfirm.addEventListener('click', confirmDelete);
  el.dialogBackdrop.addEventListener('click', function (event) {
    if (event.target === el.dialogBackdrop) {
      closeDeleteDialog();
    }
  });
  document.addEventListener('keydown', function (event) {
    if (event.key === 'Escape' && !el.dialogBackdrop.hidden) {
      closeDeleteDialog();
    }
  });

  setEditingMode(null);
  render();
}

await init();

