:root {
  --brand: #1d6fe0;
  --brand-dark: #14509f;
  --brand-soft: #e8f1fd;
  --brand-line: #cfe0f7;
  --ink: #16233a;
  --ink-soft: #5a6b85;
  --surface: #ffffff;
  --page-bg: #f2f7fe;
  --danger: #d64545;
  --danger-soft: #fdecec;
  --radius: 14px;
  --shadow: 0 6px 18px rgba(29, 111, 224, 0.10);
}

#app {
  min-height: 100vh;
  background: linear-gradient(180deg, #eaf3ff 0%, var(--page-bg) 42%, #f7fbff 100%);
  color: var(--ink);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif;
  font-size: 15px;
  line-height: 1.5;
  -webkit-text-size-adjust: 100%;
}

#app * {
  box-sizing: border-box;
}

.app-shell {
  max-width: 720px;
  margin: 0 auto;
  padding: 18px 14px 48px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.app-header {
  padding: 6px 4px 2px;
}

.app-title {
  margin: 0;
  font-size: 22px;
  font-weight: 700;
  letter-spacing: 0.5px;
  color: var(--brand-dark);
}

.app-subtitle {
  margin: 6px 0 0;
  font-size: 13px;
  color: var(--ink-soft);
}

.panel {
  background: var(--surface);
  border: 1px solid var(--brand-line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 14px;
}

.stats-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 10px;
}

.panel-title {
  margin: 0;
  font-size: 16px;
  font-weight: 700;
  color: var(--brand-dark);
}

.stats-total,
.list-count {
  font-size: 12.5px;
  color: var(--ink-soft);
  white-space: nowrap;
}

.stats-total strong,
.list-count strong {
  color: var(--brand);
  font-size: 15px;
}

.stats-grid {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.stat-item {
  background: var(--brand-soft);
  border: 1px solid var(--brand-line);
  border-radius: 12px;
  padding: 10px 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.stat-name {
  font-size: 13px;
  color: var(--ink-soft);
}

.stat-value {
  font-size: 19px;
  font-weight: 700;
  color: var(--brand-dark);
}

.record-form {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
}

.field-row {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.field label {
  font-size: 13px;
  font-weight: 600;
  color: var(--ink-soft);
}

.field input,
.field select,
.field textarea {
  width: 100%;
  font: inherit;
  color: var(--ink);
  background: #fbfdff;
  border: 1px solid var(--brand-line);
  border-radius: 10px;
  padding: 10px 11px;
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.field textarea {
  resize: vertical;
  min-height: 68px;
}

.field input:focus,
.field select:focus,
.field textarea:focus {
  border-color: var(--brand);
  box-shadow: 0 0 0 3px rgba(29, 111, 224, 0.16);
  background: #ffffff;
}

.form-error {
  margin: 0;
  padding: 8px 10px;
  font-size: 13px;
  color: var(--danger);
  background: var(--danger-soft);
  border: 1px solid #f6c9c9;
  border-radius: 10px;
}

.form-actions {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.btn {
  font: inherit;
  font-weight: 600;
  border-radius: 10px;
  border: 1px solid transparent;
  padding: 10px 16px;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease;
}

.btn-primary {
  background: var(--brand);
  color: #ffffff;
  flex: 1 1 auto;
}

.btn-primary:hover {
  background: var(--brand-dark);
}

.btn-ghost {
  background: #ffffff;
  color: var(--brand-dark);
  border-color: var(--brand-line);
}

.btn-ghost:hover {
  background: var(--brand-soft);
}

.btn-danger {
  background: var(--danger);
  color: #ffffff;
}

.btn-danger:hover {
  background: #b93a3a;
}

.btn-small {
  padding: 6px 12px;
  font-size: 13px;
  border-radius: 8px;
}

.filter-bar {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 12px;
}

.filter-chip {
  font: inherit;
  font-size: 13px;
  font-weight: 600;
  padding: 7px 13px;
  border-radius: 999px;
  border: 1px solid var(--brand-line);
  background: #ffffff;
  color: var(--ink-soft);
  cursor: pointer;
}

.filter-chip:hover {
  background: var(--brand-soft);
}

.filter-chip.is-active {
  background: var(--brand);
  border-color: var(--brand);
  color: #ffffff;
}

.record-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.record-card {
  border: 1px solid var(--brand-line);
  border-left: 4px solid var(--brand);
  border-radius: 12px;
  padding: 12px;
  background: #fdfeff;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.record-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
}

.record-company {
  margin: 0;
  font-size: 16px;
  font-weight: 700;
  color: var(--ink);
  word-break: break-word;
}

.record-position {
  margin: 2px 0 0;
  font-size: 13.5px;
  color: var(--ink-soft);
  word-break: break-word;
}

.stage-badge {
  flex: 0 0 auto;
  font-size: 12px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 999px;
  border: 1px solid transparent;
  white-space: nowrap;
}

.stage-badge[data-stage="待投递"] {
  background: #eef2f7;
  color: #4a5a72;
  border-color: #dbe3ee;
}

.stage-badge[data-stage="已投递"] {
  background: var(--brand-soft);
  color: var(--brand-dark);
  border-color: var(--brand-line);
}

.stage-badge[data-stage="面试中"] {
  background: #fff4e0;
  color: #9a6200;
  border-color: #f6dfb4;
}

.stage-badge[data-stage="已结束"] {
  background: #eef1f4;
  color: #6b7683;
  border-color: #dde3e9;
}

.record-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 14px;
  font-size: 12.5px;
  color: var(--ink-soft);
}

.record-note {
  margin: 0;
  font-size: 13px;
  color: var(--ink);
  background: var(--brand-soft);
  border-radius: 8px;
  padding: 8px 10px;
  white-space: pre-wrap;
  word-break: break-word;
}

.record-actions {
  display: flex;
  gap: 8px;
  justify-content: flex-end;
}

.empty-hint {
  margin: 4px 0 0;
  padding: 18px 12px;
  text-align: center;
  font-size: 13.5px;
  color: var(--ink-soft);
  background: var(--brand-soft);
  border: 1px dashed var(--brand-line);
  border-radius: 12px;
}

.dialog-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(16, 33, 58, 0.45);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  z-index: 50;
}

.dialog-backdrop[hidden] {
  display: none;
}

.dialog {
  width: 100%;
  max-width: 360px;
  background: var(--surface);
  border-radius: var(--radius);
  border: 1px solid var(--brand-line);
  box-shadow: 0 18px 40px rgba(16, 33, 58, 0.28);
  padding: 18px;
}

.dialog-title {
  margin: 0 0 8px;
  font-size: 17px;
  color: var(--brand-dark);
}

.dialog-desc {
  margin: 0 0 16px;
  font-size: 13.5px;
  color: var(--ink-soft);
  word-break: break-word;
}

.dialog-actions {
  display: flex;
  gap: 10px;
  justify-content: flex-end;
}

@media (max-width: 420px) {
  .app-shell {
    padding: 14px 10px 40px;
  }

  .field-row {
    grid-template-columns: 1fr;
  }

  .stats-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .btn {
    padding: 11px 14px;
  }

  .form-actions .btn {
    flex: 1 1 100%;
  }
}
